js.text:

	function grid$khxl(f){
		this.constructor(f);
	}
	grid$khxl.prototype = new DirEvent();
	grid$khxl.prototype.isModalOpen = function() {
		return $("#subcontent").find(".modal").length > 0;
	};

grid$khxl.prototype.beforeButtonGridClick = function(id, gindex, r) {
	// Kiểm tra nếu có modal đang mở
	if (this.isModalOpen()) {
		console.log("A modal is currently open. Action cannot be performed.");
		return false; // Ngừng thực hiện hành động nếu có modal mở
	}

	// Tiến hành kiểm tra bình thường nếu không có modal mở
	return true;
};
	grid$khxl.prototype.afterInit = function(){

	}

css.text:

.tree-form{
	width: 250px;
}
.ic-view-dept{
  background-position: 0px 0px;
}
.table-bottom{
	left: 0px!important;
	height: calc(100% - 77px);
	top: 0px;
	position: relative;
	margin-top: 27px;
	clear: both;
	border-bottom: 1px solid #ddd;
}
#content .dir{
	position: relative !important;
	height: 100%;
}

@media only screen and (max-width: 767px) {
  .table-bottom{
	margin-top: 42px;
	height: calc(100% - 92px);
  }
}
